  url=String(url).replace("1/","{{page}}/").replace("1.html","{{page}}.html")
        size=0.25;
        push(title,url,size)
    }
push("🌹全本🌹","/mfull/{{page}}.html",1)

}else{
  java.toast("发现列表获取失败！")
}

JSON.stringify(sort)

